// Aho-Corasick skeleton: trie + failure links via BFS
void buildFail(){
    queue<Node*> q;
    for (int c = 0; c < 26; c++)
        if (root->ch[c]) { root->ch[c]->fail = root; q.push(root->ch[c]); }
    while (!q.empty()) {
        Node* v = q.front(); q.pop();
        for (int c = 0; c < 26; c++) {
            Node* u = v->ch[c];
            if (!u) { v->ch[c] = v->fail ? v->fail->ch[c] : root; continue; }
            u->fail = v->fail ? v->fail->ch[c] : root;
            u->out += u->fail->out;
            q.push(u);
        }
    }
}
